mo.chapter4 = c4Assets;

const c4TextOverlays = {
  c4b1p1: ['c4b1p1-text'], c4b1p2: ['c4b1p2-text'],
  c4b2p1: ['c4b2p1-text'], c4b2p2: ['c4b2p2-text'], c4b2p3: ['c4b2p3-text'],
  c4b3p1: ['c4b3p1-text'], c4b3p2: ['c4b3p2-text'],
  c4b4p1: ['c4b4p1-text'], c4b4p2: ['c4b4p2-text'], c4b4p3: ['c4b4p3-text'],
  c4b5p1: ['c4b5p1-text'], c4b5p2: ['c4b5p2-text'],
  c4b6p1: ['c4b6p1-text'],
  c4b7p2: ['c4b7p2-text'], c4b7p3: ['c4b7p3-text'],
  c4b8p1: ['c4b8p1-caption', 'c4b8p1-letter']
};

class Chapter4Bg extends DJ {
  createMesh() {
    this.mesh = new ve(this.world.gl, {
      geometry: this.world.geoms.plane,
      program: this.createProgram({
        params: {},
        vertex: oe,
        fragment: UJ,
        uniforms: {
          ...this.uniforms,
          uColor1: { value: new re('#F87800') },
          uColor2: { value: new re('#EB8DB7') },
          uAlpha: { value: 1 }
        }
      })
    });
    this.mesh.position.z = -5;
    this.group.addChild(this.mesh);
  }
}

const C4_MOTION_CONFIG = {
  // 1.1 Stepped Idle
  ENABLE_STEPPED_IDLE: true,
  STEP_FPS: 12,
  BREATH_SPEED: 2.2,
  BREATH_AMP: 0.008,
  BOB_SPEED: 1.6,
  BOB_AMP: 0.012,

  // 1.2 Hair deformation
  ENABLE_HAIR_DEFORMATION: true,
  HAIR_SPEED: 3.2,
  HAIR_AMP_X: 0.0030,
  HAIR_AMP_Y: 0.0018,

  // 1.3 Staggered Entrance
  ENABLE_STAGGERED_ENTRANCE: true,
  ENTRANCE_BG_DELAY: 0.0,
  ENTRANCE_FG_DELAY: 0.10,
  ENTRANCE_OVERLAY_DELAY: 0.20,
  ENTRANCE_BUBBLE_DELAY: 0.28
};

const c4CharacterFrag = `uniform sampler2D tMap;
varying vec2 vUv;
uniform float uAlpha;
uniform float uLocalTime;
uniform float uHairEnabled;

float cmapC4(float oldValue, float oldMin, float oldMax, float newMin, float newMax) {
  return clamp((((oldValue - oldMin) * (newMax - newMin)) / (oldMax - oldMin)) + newMin, min(newMin, newMax), max(newMin, newMax));
}

void main() {
    vec2 uv = vUv;
    float dispX = 0.;
    float dispY = 0.;

    // Hair UV mask: upper region y >= 0.60, central/back hair
    float hairMask = cmapC4(uv.y, 0.60, 0.95, 0.0, 1.0) * cmapC4(abs(uv.x - 0.5), 0.0, 0.48, 1.0, 0.0);
    dispX += sin(uLocalTime * 3.2 + uv.y * 10.0) * 0.0030 * hairMask * uHairEnabled;
    dispY += cos(uLocalTime * 2.0 + uv.x * 6.0) * 0.0018 * hairMask * uHairEnabled;

    vec2 sampleUv = clamp(uv + vec2(dispX, dispY), vec2(0.001), vec2(0.999));
    vec4 color = texture2D(tMap, sampleUv);

    gl_FragColor = color;
    gl_FragColor.a *= uAlpha;
}`;

if (typeof NF !== 'undefined' && typeof oe !== 'undefined') {
  NF['c4-character'] = {
    vertex: oe,
    fragment: c4CharacterFrag,
    uniforms: {
      uHairEnabled: { value: 1.0 }
    }
  };
}

class Chapter4Panel extends me {
  constructor(world, props) {
    props.usePerspective = true;
    props.fov = 45;
    super(world, props);
    if (typeof window !== 'undefined') { (window.__C4_DEBUG__ = window.__C4_DEBUG__ || {})[props.id] = this; }
    const {
      bgTexture,
      fgTexture,
      compositeTexture,
      overlayTexture,
      zBg = -0.72,
      zFg = 0.35,
      fgScale = 0.95,
      fgOffset = { x: 0, y: 0 },
      bubbleOffsetY = 0.26,
      bubbleOffsetX = 0,
      hasBreathing = true
    } = props;

    this.hasBreathing = hasBreathing;
    this.timeAccumulator = Math.random() * 10;
    this.textOverlayMeshes = [];
    this.textOverlayTweens = [];
    this.entranceTweens = [];

    // 1. Base Plate: anti-ghosting architecture
    // Always prefer clean background texture over composite when fg cutout is present
    const plateId = (fgTexture && bgTexture) ? bgTexture : (compositeTexture || bgTexture);
    if (plateId) {
      const bgTextureMap = this.getTexture(plateId);
      const bgImage = bgTextureMap && bgTextureMap.image;
      const bgWidth = bgImage && (bgImage.naturalWidth || bgImage.width);
      const bgHeight = bgImage && (bgImage.naturalHeight || bgImage.height);
      const bgAspect = bgWidth && bgHeight ? bgWidth / bgHeight : props.ratio;

      this.bgMesh = this.createMesh({
        meshId: `${props.id}-plate`,
        id: 'map',
        uniforms: { tMap: { value: bgTextureMap } }
      });
      const distBg = 5 - zBg;
      const frustumHeightBg = 2 * Math.tan((45 * Math.PI) / 360) * distBg;
      const bgCoverScale = Math.max(1, props.ratio / bgAspect);
      this.bgMesh.oPosition.z = zBg;
      this.bgMesh.oScale.set(frustumHeightBg * bgAspect * bgCoverScale, frustumHeightBg * bgCoverScale, 1);
      this.bgMesh.sync();
    }

    // 2. Foreground Character Cutout with native aspect ratio fit
    if (fgTexture) {
      const fgTextureMap = this.getTexture(fgTexture);
      const fgImage = fgTextureMap && fgTextureMap.image;
      const fgWidth = fgImage && (fgImage.naturalWidth || fgImage.width);
      const fgHeight = fgImage && (fgImage.naturalHeight || fgImage.height);
      const fgAspect = fgWidth && fgHeight ? fgWidth / fgHeight : props.ratio;

      this.fgMesh = this.createMesh({
        meshId: `${props.id}-character`,
        id: C4_MOTION_CONFIG.ENABLE_HAIR_DEFORMATION ? 'c4-character' : 'map',
        params: { transparent: true },
        uniforms: {
          tMap: { value: fgTextureMap },
          uHairEnabled: { value: C4_MOTION_CONFIG.ENABLE_HAIR_DEFORMATION ? 1.0 : 0.0 }
        }
      });
      const distFg = 5 - zFg;
      const frustumHeightFg = 2 * Math.tan((45 * Math.PI) / 360) * distFg;
      const frustumWidthFg = frustumHeightFg * props.ratio;

      let meshW, meshH;
      if (fgAspect > props.ratio) {
        meshW = frustumWidthFg * fgScale;
        meshH = meshW / fgAspect;
      } else {
        meshH = frustumHeightFg * fgScale;
        meshW = meshH * fgAspect;
      }

      this.fgMesh.oPosition.z = zFg;
      this.fgMesh.oPosition.x = frustumWidthFg * (fgOffset.x || 0);
      this.fgMesh.oPosition.y = frustumHeightFg * (fgOffset.y || 0);
      this.fgMesh.oScale.set(meshW, meshH, 1);
      this.fgMesh.sync();
    }

    // 3. Speech Bubbles / Localized Overlays with authentic Ponpon Mania proportions
    const textTextures = [...(c4TextOverlays[props.id] || [])];
    textTextures.forEach((textureId, index) => {
      const textTextureMap = this.getTexture(textureId);
      const textImage = textTextureMap && textTextureMap.image;
      const textWidth = textImage && (textImage.naturalWidth || textImage.width);
      const textHeight = textImage && (textImage.naturalHeight || textImage.height);
      const textAspect = textWidth && textHeight ? textWidth / textHeight : 3.0;

      const textMesh = this.createMesh({
        meshId: `${props.id}-text-${index}`,
        id: 'map',
        params: { transparent: true, depthTest: false },
        uniforms: { tMap: { value: textTextureMap } }
      });
      const textZ = 0.82 + index * 0.003;
      const distText = 5 - textZ;
      const frustumHeightText = 2 * Math.tan((45 * Math.PI) / 360) * distText;
      const frustumWidthText = frustumHeightText * props.ratio;

      textMesh.oPosition.z = textZ;
      textMesh.oPosition.x = 0;
      textMesh.oPosition.y = 0;
      textMesh.oScale.set(frustumWidthText, frustumHeightText, 1);
      textMesh.sync();
      textMesh.scale.set(0, 0, 0);
      this.textOverlayMeshes.push(textMesh);
    });

    // 4. Celebration Banner (Board 7)
    if (overlayTexture) {
      this.overlayMesh = this.createMesh({
        meshId: `${props.id}-banner`,
        id: 'map',
        params: { transparent: true, depthTest: false },
        uniforms: { tMap: { value: this.getTexture(overlayTexture) } }
      });
      const distBanner = 5 - 0.85;
      const frustumHeightBanner = 2 * Math.tan((45 * Math.PI) / 360) * distBanner;
      const frustumWidthBanner = frustumHeightBanner * props.ratio;
      this.overlayMesh.oPosition.z = 0.85;
      // Positioned with precision to nestle inside the authentic cream ribbon
      this.overlayMesh.oPosition.y = frustumHeightBanner * 0.345;
      this.overlayMesh.oScale.set(frustumWidthBanner * 0.88, frustumHeightBanner * 0.17, 1);
      this.overlayMesh.sync();
      this.overlayMesh.scale.set(0, 0, 0);
    }
  }

  update(t, n) {
    super.update(t, n);
    this.timeAccumulator += (n || 16) * 0.001;

    let evalTime = this.timeAccumulator;
    if (C4_MOTION_CONFIG.ENABLE_STEPPED_IDLE && C4_MOTION_CONFIG.STEP_FPS > 0) {
      evalTime = Math.floor(evalTime * C4_MOTION_CONFIG.STEP_FPS) / C4_MOTION_CONFIG.STEP_FPS;
    }

    // A. Idle breathing & subtle stepped floating on character cutout
    if (this.fgMesh && this.fgMesh.mesh && this.hasBreathing) {
      const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (!prefersReducedMotion) {
        const breath = Math.sin(evalTime * C4_MOTION_CONFIG.BREATH_SPEED);
        const bobY = Math.sin(evalTime * C4_MOTION_CONFIG.BOB_SPEED) * C4_MOTION_CONFIG.BOB_AMP;
        this.fgMesh.mesh.scale.y = this.fgMesh.oScale.y * (1 + breath * C4_MOTION_CONFIG.BREATH_AMP);
        this.fgMesh.mesh.position.y = this.fgMesh.oPosition.y + bobY;
      }
    }

    // B. Subtle organic stepped floating on text speech bubbles
    if (this.textOverlayMeshes && this.textOverlayMeshes.length > 0) {
      this.textOverlayMeshes.forEach((mesh, idx) => {
        if (mesh && mesh.mesh && mesh.mesh.visible) {
          const floatOffset = Math.sin(evalTime * 2.2 + idx * 1.2) * 0.006;
          mesh.mesh.position.y = mesh.oPosition.y + floatOffset;
        }
      });
    }

    // C. Gentle festive sway on party banner
    if (this.overlayMesh && this.overlayMesh.mesh && this.overlayMesh.mesh.visible) {
      this.overlayMesh.mesh.rotation.z = Math.sin(evalTime * 2.5) * 0.018;
    }

    // D. Hair shader deformation update
    if (this.fgMesh && this.fgMesh.program && this.fgMesh.program.uniforms && this.fgMesh.program.uniforms.uHairEnabled) {
      const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      this.fgMesh.program.uniforms.uHairEnabled.value = (C4_MOTION_CONFIG.ENABLE_HAIR_DEFORMATION && !prefersReducedMotion) ? 1.0 : 0.0;
    }

    // E. Micro-animations and comic SFX dynamics
    const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!prefersReducedMotion) {
      // 1. Board 2 Panel 2: CLICK! camera sound effect pulse
      if (this.id === 'c4b2p2' && this.textOverlayMeshes[0] && this.textOverlayMeshes[0].mesh && this.textOverlayMeshes[0].mesh.visible) {
        const sfxPulse = Math.sin(evalTime * 4.2) * 0.045;
        this.textOverlayMeshes[0].mesh.scale.x = this.textOverlayMeshes[0].oScale.x * (1.0 + sfxPulse);
        this.textOverlayMeshes[0].mesh.scale.y = this.textOverlayMeshes[0].oScale.y * (1.0 + sfxPulse);
      }

      // 2. Board 8: Keepsake letter double-beat heartbeat pulse on letter overlay
      if (this.id === 'c4b8p1' && this.textOverlayMeshes[1] && this.textOverlayMeshes[1].mesh && this.textOverlayMeshes[1].mesh.visible) {
        const beatPhase = (evalTime * 2.2) % (Math.PI * 2);
        let heartPulse = 0;
        if (beatPhase < 0.6) {
          heartPulse = Math.sin(beatPhase * Math.PI / 0.6) * 0.038;
        } else if (beatPhase > 0.8 && beatPhase < 1.4) {
          heartPulse = Math.sin((beatPhase - 0.8) * Math.PI / 0.6) * 0.022;
        }
        this.textOverlayMeshes[1].mesh.scale.x = this.textOverlayMeshes[1].oScale.x * (1.0 + heartPulse);
        this.textOverlayMeshes[1].mesh.scale.y = this.textOverlayMeshes[1].oScale.y * (1.0 + heartPulse);
      }

      // 3. Board 3 Panel 2: Subtle typing vibration
      if (this.id === 'c4b3p2' && this.fgMesh && this.fgMesh.mesh) {
        const typingJitter = Math.sin(evalTime * 14.0) * 0.0025;
        this.fgMesh.mesh.position.y += typingJitter;
      }

      // 4. Board 1 Panel 2: Bag keychain subtle pendulum sway
      if (this.id === 'c4b1p2' && this.fgMesh && this.fgMesh.mesh) {
        this.fgMesh.mesh.rotation.z = Math.sin(evalTime * 2.6) * 0.012;
      }

      // F. Subtle cursor/touch parallax layer depth (Board 1, 3, 6, 8)
      if (this.mousePos && (this.id === 'c4b1p1' || this.id === 'c4b1p2' || this.id === 'c4b3p1' || this.id === 'c4b3p2' || this.id === 'c4b6p1' || this.id === 'c4b8p1')) {
        const mx = (this.mousePos.x - 0.5);
        if (this.fgMesh && this.fgMesh.mesh) {
          this.fgMesh.mesh.position.x = this.fgMesh.oPosition.x + mx * 0.025;
        }
        if (this.bgMesh && this.bgMesh.mesh) {
          this.bgMesh.mesh.position.x = this.bgMesh.oPosition.x - mx * 0.010;
        }
      }
    }
  }

  onEnterCb() {
    super.onEnterCb();
    const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.textOverlayTweens.forEach(tween => tween.kill());
    this.textOverlayTweens = [];
    if (this.entranceTweens) {
      this.entranceTweens.forEach(t => t.kill());
    }
    this.entranceTweens = [];

    if (!C4_MOTION_CONFIG.ENABLE_STAGGERED_ENTRANCE || prefersReducedMotion) {
      if (this.bgMesh) { this.bgMesh.scale.copy(this.bgMesh.oScale); }
      if (this.fgMesh) { this.fgMesh.scale.copy(this.fgMesh.oScale); this.fgMesh.position.copy(this.fgMesh.oPosition); }
      if (this.overlayMesh) { this.overlayMesh.mesh.visible = true; this.overlayMesh.scale.copy(this.overlayMesh.oScale); }
      this.textOverlayMeshes.forEach(mesh => {
        mesh.mesh.visible = true;
        mesh.scale.copy(mesh.oScale);
      });
      return;
    }

    // 1. Background subtle settle
    if (this.bgMesh) {
      this.bgMesh.scale.set(this.bgMesh.oScale.x * 0.98, this.bgMesh.oScale.y * 0.98, this.bgMesh.oScale.z);
      this.entranceTweens.push(
        S.to(this.bgMesh.scale, {
          x: this.bgMesh.oScale.x,
          y: this.bgMesh.oScale.y,
          z: this.bgMesh.oScale.z,
          duration: 0.55,
          ease: 'power2.out'
        })
      );
    }

    // 2. Character cutout pop-in with slight vertical settle
    if (this.fgMesh) {
      this.fgMesh.scale.set(this.fgMesh.oScale.x * 0.92, this.fgMesh.oScale.y * 0.92, this.fgMesh.oScale.z);
      this.fgMesh.position.y = this.fgMesh.oPosition.y - 0.035;
      this.entranceTweens.push(
        S.to(this.fgMesh.scale, {
          x: this.fgMesh.oScale.x,
          y: this.fgMesh.oScale.y,
          z: this.fgMesh.oScale.z,
          duration: 0.48,
          delay: C4_MOTION_CONFIG.ENTRANCE_FG_DELAY,
          ease: 'back.out(1.4)'
        })
      );
      this.entranceTweens.push(
        S.to(this.fgMesh.position, {
          y: this.fgMesh.oPosition.y,
          duration: 0.44,
          delay: C4_MOTION_CONFIG.ENTRANCE_FG_DELAY,
          ease: 'power2.out'
        })
      );
    }

    // 3. Overlay mesh (e.g. party banners)
    if (this.overlayMesh) {
      this.overlayMesh.mesh.visible = true;
      this.overlayMesh.scale.set(0, 0, 0);
      this.entranceTweens.push(
        S.to(this.overlayMesh.scale, {
          x: this.overlayMesh.oScale.x,
          y: this.overlayMesh.oScale.y,
          z: this.overlayMesh.oScale.z,
          duration: 0.44,
          delay: C4_MOTION_CONFIG.ENTRANCE_OVERLAY_DELAY,
          ease: 'back.out(1.6)'
        })
      );
    }

    // 4. Staggered speech bubbles
    this.textOverlayTweens = this.textOverlayMeshes.map((mesh, idx) => {
      mesh.mesh.visible = true;
      mesh.scale.set(0, 0, 0);
      return S.to(mesh.scale, {
        x: mesh.oScale.x,
        y: mesh.oScale.y,
        z: mesh.oScale.z,
        duration: 0.40,
        delay: C4_MOTION_CONFIG.ENTRANCE_BUBBLE_DELAY + idx * 0.12,
        ease: 'back.out(1.6)'
      });
    });
  }

  onLeaveCb() {
    super.onLeaveCb();
    if (this.entranceTweens) {
      this.entranceTweens.forEach(t => t.kill());
      this.entranceTweens = [];
    }
    this.textOverlayTweens.forEach(tween => tween.kill());
    this.textOverlayTweens = this.textOverlayMeshes.map(mesh => S.to(mesh.scale, {
      x: 0,
      y: 0,
      z: 0,
      duration: 0.18,
      ease: 'power2.in',
      onComplete: () => { mesh.mesh.visible = false; }
    }));

    if (this.overlayMesh) {
      S.to(this.overlayMesh.scale, {
        x: 0,
        y: 0,
        z: 0,
        duration: 0.18,
        ease: 'power2.in',
        onComplete: () => { this.overlayMesh.mesh.visible = false; }
      });
    }

    if (this.fgMesh) {
      S.to(this.fgMesh.scale, {
        x: this.fgMesh.oScale.x * 0.92,
        y: this.fgMesh.oScale.y * 0.92,
        duration: 0.18,
        ease: 'power2.in'
      });
    }
  }
}

class Board4_1 extends St {
  constructor(t, n) {
    super(t, { chapter: n.chapter, ratio: 1, index: n.index });
    h(this, 'topPanel');
    h(this, 'bottomPanel');
    h(this, 'lamaClouds');
    this.initPanels();
    this.lamaClouds = new fJ(this.world, { scene: n.chapter, board: this });
    this.plane.addChild(this.lamaClouds.plane);
  }
  initPanels() {
    let t = this.squarePos, n = this.squareSize;
    this.topPanel = new Chapter4Panel(this.world, {
      ...this.defaultProps,
      id: 'c4b1p1',
      position: { x: 0, y: t },
      size: { x: n * 2.1, y: n },
      ratio: 2.1,
      bgTexture: 'c4b1p1-bg',
      fgTexture: 'c4b1p1-fg',
      compositeTexture: 'c4b1p1-composite',
      fgScale: 0.95,
      fgOffset: { x: 0.18, y: -0.04 },
      bubbleOffsetY: 0.28,
      bubbleOffsetX: -0.15
    });
    this.addPanel(this.topPanel);
    this.bottomPanel = new Chapter4Panel(this.world, {
      ...this.defaultProps,
      id: 'c4b1p2',
      position: { x: 0, y: -t },
      size: { x: n * 2.1, y: n },
      ratio: 2.1,
      bgTexture: 'c4b1p2-bg',
      fgTexture: 'c4b1p2-fg',
      compositeTexture: 'c4b1p2-composite',
      fgScale: 0.95,
      fgOffset: { x: -0.15, y: -0.04 },
      bubbleOffsetY: 0.28,
      bubbleOffsetX: 0.20
    });
    this.addPanel(this.bottomPanel);
  }
  onMouseMove(t) {
    super.onMouseMove(t);
    this.isInView && (this.lamaClouds.resetState = !1);
  }
  unbind() {
    super.unbind();
    this.lamaClouds.animateOut();
  }
  onEnterCb() {
    super.onEnterCb();
    this.lamaClouds.animateIn();
  }
  onLeaveCb() {
    super.onLeaveCb();
    this.lamaClouds.animateOut();
  }
  update(t, n) {
    super.update(t, n);
    this.lamaClouds.update(t, n);
    const prefersReducedMotion = typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!prefersReducedMotion) {
      if (this.bottomPanel && this.bottomPanel.bgMesh && this.bottomPanel.bgMesh.program && this.bottomPanel.bgMesh.program.uniforms && this.bottomPanel.bgMesh.program.uniforms.uAlpha) {
        const flicker = 0.96 + Math.sin(t * 6.5) * 0.02 + Math.sin(t * 14.2) * 0.02;
        this.bottomPanel.bgMesh.program.uniforms.uAlpha.value = flicker;
      }
      if (this.topPanel && this.topPanel.bgMesh && this.topPanel.bgMesh.program && this.topPanel.bgMesh.program.uniforms && this.topPanel.bgMesh.program.uniforms.uAlpha) {
        const flickerTop = 0.97 + Math.cos(t * 5.8) * 0.02 + Math.sin(t * 12.1) * 0.01;
        this.topPanel.bgMesh.program.uniforms.uAlpha.value = flickerTop;
      }
    }
  }
}

